B="BK-741"
C=[
("S19",5100,5101,"الفراسة (قراءة الطباع من الشكل) لا تصلح أساساً للاستدلال","يعدّ الكتاب الفراسة من العلوم القديمة التي يمكن أن يستدل بها على أخلاق الناس من هيئتهم. المنهج الحديث لا يقبل هذه القراءة دليلاً، ويحذّر من الأحكام المسبقة على الأشخاص بسبب مظهرهم أو سلوكهم العام.","في اللعبة: مشتبه 'مريب المنظر' ليس أكثر شبهة من غيره؛ ابحث في الأدلة لا في الملامح.","لا يوجد دليل علمي على أن الملامح أو الحركات تكشف الكذب أو الإجرام.","من يتجنب النظر في العينين كاذب، ومن يبدو شريراً فهو مجرم.","13-15","safe","witness_reliability",["KO-RS-05-007","KO-RS-06-020"],["فراسة","تحيّز مظهر"]),
("S19",5102,5125,"التخفّي يستعمل لمراقبة المشتبه به، وكشف تنكّر الجناة جزء من العمل","يذكر الكتاب أن الباحث قد يتخفّى لمراقبة أو لإجراء حديث، وأن الجناة قد يغيّرون مظهرهم أو يزيلون علامات مميزة. القاعدة الاستقصائية: لا تعتمد على الوصف المظهري وحده في الاستعراف.","في الألغاز: شخص ظهر بوصفين مختلفين في شهادتين؛ فكّر هل هي شخصان أم شخص واحد غيّر مظهره، وما الذي لا يتغير؟","الأوصاف المظهرية تتغير بسهولة وتحتاج إلى سمات ثابتة.","","13-15","safe","witness_reliability",["KO-RS-05-008","KO-RS-05-004"],["تنكر","سمات ثابتة"]),
("S20",5137,5155,"قبل المعاينة: خطة وهدوء وحراسة وفصل الشهود وإغلاق المكان","يلخص الكتاب ما يفعله المحقق عند البلاغ: رسم خطة، الثقة بالنفس دون عاطفة، منع غير المسؤولين من الدخول، عدم تحريك شيء قبل الخبير، إسعاف المصابين، تحديد الخبراء، عدم التسرع في إبداء الرأي، التحفظ على المتهمين، الاهتمام بمن بلّغ، فصل الشهود، ثم ختم المكان وحراسته.","اجعل هذه القائمة بطاقة ملاحظة في اللعبة وراجع ما فاتك في كل مشهد.","التسلسل المثالي يتأثر بخطر فوري أو بزحام.","المبلّغ دائماً بريء أو دائماً مشتبه.","all","safe","scene_documentation",["KO-FC-04-026","KO-RS-05-002","KO-RS-05-008","KO-FC-04-027"],["معاينة","فصل الشهود"]),
("S20",5152,5152,"لا تدع فكرة مسبقة تسيطر على المعاينة","ينبه الكتاب إلى ألا يتسرع المحقق في إبداء رأيه وألا تسيطر عليه فكرة معينة قادمة من البلاغ أو من الظاهر. هذا وصف مبكر لما تسميه الأدبيات الحديثة التحيز التأكيدي.","اكتب ثلاث فرضيات على الأقل قبل أن ترجح إحداها، وحدّد ما يستبعد كلاً منها.","وعي المحقق بالتحيز لا يلغيه وحده؛ تفيد المراجعة المستقلة.","","all","safe","reporting",["KO-FC-04-027","KO-RS-05-002","KO-RS-06-006"],["تحيز تأكيدي","فرضيات متعددة"]),
("S20",5156,5167,"المعاينة الفنية خمسة أنشطة: الوصف والتصوير والرسم والرفع وتفتيش المشتبه","يعدد الكتاب إجراءات الفنيين: الوصف بالكتابة، التصوير، الرسم الهندسي، رفع الآثار المادية، وتفتيش الجاني وشركائه. كل نشاط يوثق جانباً مختلفاً، وبعضها يكمل بعضاً.","في اللعبة: لكل مشهد خانات الأنشطة الخمسة، وتُكمل الحالة بأنشطة متعددة لا بنشاط واحد.","كل وسيلة توثيق تُغفل أشياء، والصورة لا تغني عن الوصف.","","all","safe","scene_documentation",["KO-FC-04-026","KO-FC-04B-002"],["وصف","تصوير","رسم"]),
("S20",5168,5190,"الآثار نوعان: ظاهر وخفي، والظاهر يُصوَّر قبل أن يُرفع","يفرق الكتاب بين أثر يُرى بالعين وآخر يحتاج إظهاراً، ويقول إن الظاهر يُصوَّر قبل رفعه ثم يُجمع، ثم يأتي الخفي بحذر. يحدد نوع الجريمة أين تُبحث الآثار، وتُجمع كمية كافية للتجارب مع إبقاء جزء احتياطي.","قبل رفع أي أثر اسأل: هل صُوِّر في موضعه؟ هل بقيت منه عينة للإعادة؟","الجمع الخاطئ قد يبدل الأثر أو يلوثه.","","all","safe","evidence_handling",["KO-FC-04-026","KO-FC-04-007","KO-FC-04-019"],["أثر ظاهر","أثر خفي","عينة احتياطية"]),
("S20",5190,5191,"بطاقة الحرز تحمل المكان والنوع والحالة والتواريخ","يوصي الكتاب بوضع كل أثر في حرز ملائم لحالته مع بطاقة تذكر موضع وجوده ونوعه وتاريخ رفعه وحفظه. البطاقة جزء من سلسلة الحيازة.","اطلب بطاقة الحرز دائماً؛ غيابها يضعف قيمة الدليل.","البطاقة لا تثبت أن محتوى الحرز هو ما كُتب إن لم تُراقَب عملية الجمع.","","all","safe","evidence_handling",["KO-FC-04-026","KO-FC-04B-002"],["بطاقة","سلسلة حيازة"]),
("S20",5192,5200,"فحص المشتبه به وملابسه يبدأ من نوع الجريمة","يرى الكتاب أن البحث عن آثار على الجاني يتحدد بنوع الجريمة، ويشمل ملابسه وأظافره وجيوبه، مع وصف دقيق لمكان وجود كل شيء وتحريزه. تُوثق حالة المشتبه به لحظة الضبط.","اسأل: ما الأثر الذي كان يمكن أن ينتقل من المسرح إليه، وهل بحثنا عنه قبل أن يغتسل أو يبدّل ثيابه؟","العثور على أثر مرتبط بالمكان لا يثبت أنه فعل شيئاً؛ قد يكون زاره بريئاً.","","16-18","conceptual","evidence_handling",["KO-FC-04-007","KO-FC-04-020","KO-FC-04-026"],["تفتيش","انتقال أثر"]),
("S20",5201,5236,"آثار الأدوات: ضغط واحتكاك، والمقارنة تتأثر بطريقة الاستعمال","يشرح الكتاب أن الأداة تترك أثر ضغط أو احتكاك، وأن المقارنة مع أداة مشتبه بها تحتاج أثراً تجريبياً من مادة مماثلة. وتعترضها صعوبات: طريقة إمساك الأداة وزاويتها واتساع الجزء المستعمل ونوع المادة. وهو يناقش أيضاً عدد خطوط التطابق المطلوب وينتقد القاعدة التي تربطه بعدد الخطوط.","اسأل: هل أُنتج أثر تجريبي بزوايا متعددة؟ ومن قارن؟ وهل وُثّق الاختلاف إلى جانب التشابه؟","مقارنة آثار الأدوات من أضعف فروع الأدلة المقارنة علمياً، ولا يوجد معيار ثابت لعدد الخطوط.","الأثر على الباب يثبت أداة بعينها.","16-18","conceptual","lab_limits",["KO-FC-04-016","KO-FC-04B-005","KO-FC-04-031"],["أثر أداة","أثر تجريبي"]),
("S20",5237,5271,"آثار الأقدام قد تكون قرينة وقد تكون أقوى بحسب حالتها","يقول الكتاب إن قيمة أثر القدم تتفاوت بحسب وضوحه وسطحه، فقد يكون قرينة فقط أو أقوى من ذلك، ويبدأ التعامل مع الأثر بتصويره بمسطرة وبإضاءة مناسبة قبل أي رفع. ويمكن استنتاج اتجاه السير ونمطه وعمقه الدال على الحمولة أو السرعة وتقدير تقريبي لعمر صاحبه.","قبل التفسير: صوّر الأثر بمقياس وقدّر أن الاستنتاج عن السرعة والحمل احتمالي.","استنتاجات طريقة السير من الأثر الواحد تقديرية، ومقاس الحذاء لا يحدد حاملاً بعينه.","الأثر يعطي طول القامة ووزن الشخص بدقة.","13-15","conceptual","scene_documentation",["KO-FC-04-015","KO-FC-04-026","KO-RS-06-001"],["أثر حذاء","تصوير بمسطرة"]),
("S20",5272,5288,"آثار إطارات المركبات تدل على النوع والاتجاه ومكان الوقوف","ذكر الكتاب أن آثار الإطارات قد تدل على نوع المركبة وحجمها واتجاه حركتها وأماكن وقوفها، وأن بقع الزيت والأتربة المتساقطة منها قد تدل على المناطق التي مرت بها. تُقارن بمجموعات مرجعية للإطارات.","في الألغاز: اربط أثر إطار بجدول زمني للمركبات المتاحة في المنطقة.","النوع الشائع من الإطارات يشترك فيه عدد كبير من المركبات.","","13-15","safe","scene_documentation",["KO-FC-04-015","KO-RS-06-010"],["إطار","مركبة"]),
("S20",5289,5300,"الحريق: الأول هو التمييز بين العمد والعرضي، وهو يحتاج خبيراً","يقول الكتاب إن أول سؤال في الحريق هو هل هو عمدي أم نتيجة إهمال أو حادث، وإن الإجابة تحتاج خبيراً يعرف الآثار التي يتركها المسبب. يتطلب الحريق وقوداً ومصدر اشتعال وأكسجيناً، وفهم هذه الثلاثة يقود إلى البحث عن مصدر البدء.","اسأل: ما الوقود؟ ما مصدر الحرارة الممكن؟ أين بدأ؟ وهل تتفق كل الإجابات مع الرواية؟","لا يوجد مؤشر واحد يحسم العمد، ويحتاج الأمر لمجموعة قرائن وفحص مختبري.","الحريق الكبير يعني أنه عمدي.","16-18","conceptual","reporting",["KO-RS-05-002","KO-RS-06-006","KO-FC-04-022"],["وقود","مصدر اشتعال","عمد أو حادث"]),
("S20",5298,5375,"مصادر الحريق العرضية كثيرة: كهرباء وغاز وحرارة وغبار واشتعال ذاتي","يعرض الكتاب أسباباً طبيعية أو عرضية للحريق (أعطال كهربائية، مواقد، غازات متسربة، إشعاع حراري، غبار قابل للاشتعال، اشتعال ذاتي لمواد مخزّنة، كائنات صغيرة تسبب ماساً). الفكرة الاستقصائية: قبل افتراض الفعل المتعمد استنفد التفسيرات العرضية المعقولة. لا نذكر طرق إشعال متعمد.","ضع في الجدول تفسيراً عرضياً لكل مصدر محتمل في المكان واسأل ما الأثر الذي يميّز كلاً منها.","وجود مصدر عرضي محتمل لا ينفي العمد، وغيابه لا يثبته.","","16-18","conceptual","reporting",["KO-RS-06-006","KO-RS-06-007","KO-RS-05-002"],["اشتعال عرضي","استبعاد"]),
("S20",5376,5405,"كشف سبب الحريق: نقطة البدء ثم الشهود ثم العينات ثم مداخل المبنى","يذكر الكتاب خطوات منها دراسة طبيعة المكان ومصدر الحرارة وتحديد مكان بدء النار (بأقوال الشهود وعلاماتها)، ولون الدخان ورائحته، وحالة الجو، وتعدد أماكن الاشتعال، وأخذ عينات من البقايا، وحالة الأبواب والأقفال. تعدد بؤر الاشتعال قرينة على فعل بشري لكنه ليس دليلاً قاطعاً.","اربط كل قرينة بخطوة: أين بدأ؟ هل في أكثر من نقطة؟ وهل الأبواب مغلقة من الداخل أو الخارج؟","نتائج رائحة الدخان ولونه تقديرية، وتحتاج تأكيداً بالتحليل.","","16-18","conceptual","scene_documentation",["KO-FC-04-026","KO-FC-04-019","KO-RS-05-005"],["نقطة البدء","بؤر متعددة"]),
("S20",5406,5414,"من يقف يتفرج على الحريق قد يكون له علاقة، لكنها فرضية لا حكم","يذكر الكتاب أن بعض مرتكبي الحرائق قد يحضرون إلى مكان الحريق لمتابعته، ويصنفهم إلى مضطربين نفسياً وآخرين لهم مصلحة. الاستنتاج هنا سلوكي ضعيف ولا يصلح قاعدة لاتهام الحاضرين.","سجّل أسماء الحاضرين وصورهم كمعلومة، ولا تقدّم حضور أحدهم على أنه دليل.","حضور الناس لمشاهدة الحريق ظاهرة عادية جداً.","من يحضر لمشاهدة الحريق فهو الفاعل.","16-18","conceptual","witness_reliability",["KO-RS-05-007","KO-RS-06-010","KO-RS-06-015"],["حضور المتفرجين","نسبة أساس"]),
("S20",5415,5439,"الأتربة أثر دقيق ينتقل بين الأماكن ويُقارن بالمجهر والتحليل","يذكر الكتاب أن الأتربة التي تعلق بالملابس والأحذية تحمل عناصر من أماكن مرّ بها الشخص (طين، رمل، مساحيق، ألياف، مواد عضوية) وأن المقارنة تتم بالمجهر والتحليل الطيفي. وتدل اختلافاتها بسهولة على عدم الانتماء، أما التماثل فيدعم الصلة ولا يثبتها.","استعمل منطق الاستبعاد: عدم التطابق ينفي أسهل من أن يثبت التطابق.","التراب المتماثل قد يوجد في أماكن عديدة متجاورة.","","16-18","conceptual","lab_limits",["KO-FC-04-007","KO-FC-04-019","KO-RS-06-001"],["أتربة","استبعاد"]),
("S20",5440,5455,"الزجاج المكسور لا يُلمس ويُحفظ كما وُجد قبل المقارنة","يذكر الكتاب أن شظايا الزجاج في المسرح أو على الملابس تُترك في موضعها وتُجمع بعناية، ثم تُقارن مختبرياً بخواص مثل الانكسار والكثافة والتركيب. بعض الأنواع شائعة جداً فلا يميز الزجاج العادي إلا اختبار دقيق.","اسأل: كم قطعة وجدنا على المشتبه؟ فكثرتها تعزز الصلة أكثر من قطعة واحدة.","الزجاج العادي يتشابه كثيراً في تركيبه بين المنتجين.","","16-18","conceptual","lab_limits",["KO-FC-04-019","KO-FC-04-007","KO-RS-06-010"],["زجاج","تركيب مشترك"]),
]
